import threading
from datetime import timezone, datetime
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

from .store import Store
from .meridian import MeridianClient


def _utc_now_rfc3339() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


class VendorSyncHandler(BaseHTTPRequestHandler):
    store: "Store" = None  # type: ignore[assignment]
    client: "MeridianClient" = None  # type: ignore[assignment]

    def log_message(self, format, *args):
        pass  # silence default logging

    def _send_json(self, code: int, obj: dict) -> None:
        body = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _read_body(self) -> bytes:
        length = int(self.headers.get("Content-Length", 0))
        return self.rfile.read(length) if length > 0 else b""

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        qs = parse_qs(parsed.query)

        if path == "/api/health":
            self._handle_health()
        elif path == "/api/payments":
            self._handle_payments(qs)
        elif path == "/api/summary":
            self._handle_summary()
        elif path == "/":
            self._serve_index()
        else:
            self._send_json(404, {"error": "not_found"})

    def do_POST(self) -> None:
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"

        if path == "/api/sync":
            self._read_body()
            self._handle_sync()
        else:
            self._send_json(404, {"error": "not_found"})

    # ---------- handlers ----------

    def _handle_health(self) -> None:
        self._send_json(200, {
            "status": "ok",
            "payments": self.store.count(),
            "last_sync": self.store.last_sync(),
        })

    def _handle_payments(self, qs: dict[str, list[str]]) -> None:
        # validate limit
        try:
            limit = int(qs.get("limit", ["25"])[0])
        except (ValueError, IndexError):
            self._send_json(400, {"error": "bad_request"})
            return
        if limit < 0 or limit > 100:
            self._send_json(400, {"error": "bad_request"})
            return

        # validate offset
        try:
            offset = int(qs.get("offset", ["0"])[0])
        except (ValueError, IndexError):
            self._send_json(400, {"error": "bad_request"})
            return
        if offset < 0:
            self._send_json(400, {"error": "bad_request"})
            return

        all_payments = self.store.all_payments()
        all_payments.sort(key=lambda p: p["created_at_utc"])
        total = len(all_payments)
        page = all_payments[offset : offset + limit]

        data = [
            {
                "id": p["id"],
                "amount_minor": p["amount_minor"],
                "currency": p["currency"],
                "created_at": p["created_at"],
                "status": p["status"],
            }
            for p in page
        ]

        self._send_json(200, {
            "data": data,
            "total": total,
            "limit": limit,
            "offset": offset,
        })

    def _handle_summary(self) -> None:
        payments = self.store.all_payments()
        count = len(payments)
        total_minor = sum(p["amount_minor"] for p in payments)

        oldest = None
        newest = None
        if payments:
            by_time = sorted(payments, key=lambda p: p["created_at_utc"])
            oldest_row = by_time[0]
            newest_row = by_time[-1]

            # Convert created_at_utc (float) to UTC RFC3339 with Z suffix
            def _epoch_to_rfc3339(epoch_float: float) -> str:
                return datetime.fromtimestamp(epoch_float, tz=timezone.utc).strftime(
                    "%Y-%m-%dT%H:%M:%SZ"
                )

            oldest = _epoch_to_rfc3339(oldest_row["created_at_utc"])
            newest = _epoch_to_rfc3339(newest_row["created_at_utc"])

        self._send_json(200, {
            "count": count,
            "total_minor": total_minor,
            "currency": "EUR",
            "oldest": oldest,
            "newest": newest,
        })

    def _handle_sync(self) -> None:
        try:
            fetched = self.client.fetch_all_payments()
            inserted = self.store.upsert_many(fetched)
            self.store.set_last_sync(_utc_now_rfc3339())
            self._send_json(200, {
                "fetched": len(fetched),
                "inserted": inserted,
                "total": self.store.count(),
            })
        except Exception:
            self._send_json(500, {"error": "sync_failed"})

    def _serve_index(self) -> None:
        import os
        index_path = os.path.join(os.path.dirname(__file__), "web", "index.html")
        try:
            with open(index_path, "r", encoding="utf-8") as f:
                html = f.read()
            body = html.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        except FileNotFoundError:
            self._send_json(404, {"error": "not_found"})


def serve(port: int, store: Store, client: MeridianClient) -> None:
    server_address = ("127.0.0.1", port)
    httpd = HTTPServer(server_address, VendorSyncHandler)

    # inject dependencies into handler class
    VendorSyncHandler.store = store
    VendorSyncHandler.client = client

    print(f"vendorsync HTTP server listening on http://127.0.0.1:{port}")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down...")
        httpd.shutdown()
