<div class="container">
  <header>
    <h1>VendorSync Dashboard</h1>
    <button id="syncBtn" class="btn-sync">Sync now</button>
  </header>

  <div id="summaryBar" class="summary-bar" style="display:none;">
    <div class="stat">
      <span class="stat-label">Payments</span>
      <span id="payCount" class="stat-value">0</span>
    </div>
    <div class="stat">
      <span class="stat-label">Total</span>
      <span id="payTotal" class="stat-value">€0.00</span>
    </div>
    <div id="lastSyncDisplay" class="last-sync-info"></div>
  </div>

  <div id="stateLoading" class="state-loading">
    <div class="spinner"></div>
    <p>Loading payments… If this takes longer than 10 seconds, check the server is running.</p>
  </div>

  <div id="stateEmpty" class="state-empty" style="display:none;">
    <p><strong>No payments yet.</strong> Click 'Sync now' to pull from Meridian.</p>
  </div>

  <div id="stateError" class="state-error" style="display:none;">
    <p><strong>Could not reach the backend.</strong> Ensure vendorsync is running on this machine and try again.</p>
    <p id="errorDetail"></p>
  </div>

  <div id="tableWrap" style="display:none;">
    <table>
      <thead>
        <tr><th>Date</th><th>Amount</th><th>Status</th></tr>
      </thead>
      <tbody id="paymentsBody"></tbody>
    </table>
  </div>
</div>

<script>
(function () {
  const TIMEOUT_MS = 10000;

  const elStateLoading = document.getElementById("stateLoading");
  const elStateEmpty = document.getElementById("stateEmpty");
  const elStateError = document.getElementById("stateError");
  const elErrorDetail = document.getElementById("errorDetail");
  const elSummaryBar = document.getElementById("summaryBar");
  const elPayCount = document.getElementById("payCount");
  const elPayTotal = document.getElementById("payTotal");
  const elLastSyncDisplay = document.getElementById("lastSyncDisplay");
  const elTableWrap = document.getElementById("tableWrap");
  const elPaymentsBody = document.getElementById("paymentsBody");
  const elSyncBtn = document.getElementById("syncBtn");

  function showLoading() {
    elStateLoading.style.display = "";
    elStateEmpty.style.display = "none";
    elStateError.style.display = "none";
    elSummaryBar.style.display = "none";
    elTableWrap.style.display = "none";
  }

  function showError(detail) {
    elStateLoading.style.display = "none";
    elStateEmpty.style.display = "none";
    elStateError.style.display = "";
    elSummaryBar.style.display = "none";
    elTableWrap.style.display = "none";
    elErrorDetail.textContent = detail || "";
  }

  function formatEuro(minorUnits) {
    const abs = Math.abs(minorUnits);
    const whole = Math.floor(abs / 100);
    const frac = abs % 100;
    const sign = minorUnits < 0 ? "-" : "";
    return sign + "€" + whole.toLocaleString("en-US") + "." + String(frac).padStart(2, "0");
  }

  function formatDate(rfc3339) {
    try {
      const d = new Date(rfc3339);
      if (isNaN(d.getTime())) return rfc3339;
      return d.toLocaleDateString(undefined, {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    } catch {
      return rfc3339;
    }
  }

  function formatLastSync(iso) {
    if (!iso) return "Never synced";
    try {
      const d = new Date(iso);
      if (isNaN(d.getTime())) return iso;
      return "Last sync: " + d.toLocaleString();
    } catch {
      return iso;
    }
  }

  function fetchWithTimeout(url, options) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
    return fetch(url, { ...options, signal: controller.signal })
      .finally(() => clearTimeout(timer));
  }

  async function loadData() {
    showLoading();

    try {
      const [healthRes, paymentsRes] = await Promise.all([
        fetchWithTimeout("/api/health"),
        fetchWithTimeout("/api/payments?limit=100&offset=0"),
      ]);

      if (!healthRes.ok) {
        showError("Health check failed: " + healthRes.status);
        return;
      }
      if (!paymentsRes.ok) {
        showError("Payments fetch failed: " + paymentsRes.status);
        return;
      }

      const health = await healthRes.json();
      const paymentsData = await paymentsRes.json();

      render(health, paymentsData);
    } catch (err) {
      const msg = err.name === "AbortError"
        ? "Request timed out after 10 seconds."
        : err.message || String(err);
      showError(msg);
    }
  }

  function render(health, paymentsData) {
    const count = health.payments;
    const payments = paymentsData.data || [];

    // summary
    elPayCount.textContent = count.toLocaleString();
    elLastSyncDisplay.textContent = formatLastSync(health.last_sync);

    if (count === 0) {
      elStateEmpty.style.display = "";
      elSummaryBar.style.display = "";
      elTableWrap.style.display = "none";
      elPayTotal.textContent = "€0.00";
      return;
    }

    // total from summary endpoint if available, otherwise compute from data
    const totalMinor = paymentsData.total_minor || payments.reduce((s, p) => s + (p.amount_minor || 0), 0);
    elPayTotal.textContent = formatEuro(totalMinor);

    elStateEmpty.style.display = "none";
    elSummaryBar.style.display = "flex";
    elTableWrap.style.display = "";

    // table rows
    elPaymentsBody.innerHTML = "";
    for (const p of payments) {
      const tr = document.createElement("tr");

      const tdDate = document.createElement("td");
      tdDate.textContent = formatDate(p.created_at);

      const tdAmount = document.createElement("td");
      tdAmount.textContent = formatEuro(p.amount_minor);

      const tdStatus = document.createElement("td");
      const statusClass = "status-" + (p.status || "").toLowerCase();
      tdStatus.className = statusClass;
      tdStatus.textContent = p.status || "";

      tr.appendChild(tdDate);
      tr.appendChild(tdAmount);
      tr.appendChild(tdStatus);
      elPaymentsBody.appendChild(tr);
    }
  }

  async function syncNow() {
    elSyncBtn.disabled = true;
    elSyncBtn.textContent = "Syncing…";
    showLoading();

    try {
      const res = await fetchWithTimeout("/api/sync", { method: "POST" });
      if (!res.ok) {
        showError("Sync failed: " + res.status);
        return;
      }
      await loadData();
    } catch (err) {
      showError(err.name === "AbortError" ? "Sync timed out." : err.message || String(err));
    } finally {
      elSyncBtn.disabled = false;
      elSyncBtn.textContent = "Sync now";
    }
  }

  elSyncBtn.addEventListener("click", syncNow);
  loadData();
})();
</script>
</body>
</html>
